size(150);
defaultpen(linewidth(0.7pt)+fontsize(8));

int i = 1;

draw((0,i*5)--(60,i*5)); ++i;

fill(shift(12,0)*((4,0)--(4,15)--(8,15)--(8,0)--cycle),orange);
draw(shift(12,0)*((4,0)--(4,15)^^(8,0)--(8,15)));
draw((0,i*5)--(60,i*5)); ++i;

fill((4,0)--(4,18)--(8,18)--(8,0)--cycle,orange);
draw((4,0)--(4,18));
draw((8,0)--(8,18));

for(i = 3; i <= 4; ++i)
{
draw((0,i*5)--(60,i*5));
}

